changeSet.sql:
CREATE EXTENSION IF NOT EXISTS "uuid-ossp";

CREATE TABLE IF NOT EXISTS "user".blog (
    id                 UUID PRIMARY KEY DEFAULT uuid_generate_v4() NOT NULL,
    title_uz           TEXT, title_ru TEXT, title_en TEXT,
    body_uz            TEXT, body_ru TEXT, body_en TEXT,
    image              TEXT,
    date               TIMESTAMP,
    is_home            BOOLEAN DEFAULT FALSE,
    is_send            BOOLEAN,
    is_deleted         BOOLEAN DEFAULT FALSE,
    created_date       TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    last_modified_date TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX IF NOT EXISTS user_idx_blog_home ON "user".blog (is_home);

CREATE TABLE IF NOT EXISTS "user".banner (
    id                 UUID PRIMARY KEY DEFAULT uuid_generate_v4() NOT NULL,
    title_uz           TEXT, title_ru TEXT, title_en TEXT,
    image              TEXT NOT NULL,
    link               TEXT,
    sort_order         INT NOT NULL DEFAULT 0,
    is_active          BOOLEAN NOT NULL DEFAULT TRUE,
    is_deleted         BOOLEAN NOT NULL DEFAULT FALSE,
    created_date       TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    last_modified_date TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX IF NOT EXISTS user_idx_banner_active ON "user".banner (is_active);
CREATE INDEX IF NOT EXISTS user_idx_banner_sort ON "user".banner (sort_order);

CREATE TABLE IF NOT EXISTS "user".story (
    id                 UUID PRIMARY KEY DEFAULT uuid_generate_v4() NOT NULL,
    title_uz           TEXT, title_ru TEXT, title_en TEXT,
    avatar             TEXT,
    items              TEXT,
    is_deleted         BOOLEAN DEFAULT FALSE,
    created_date       TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    last_modified_date TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX IF NOT EXISTS user_idx_story_deleted ON "user".story (is_deleted);

CREATE TABLE IF NOT EXISTS "user".story_view (
    id        UUID PRIMARY KEY DEFAULT uuid_generate_v4() NOT NULL,
    story_id  UUID NOT NULL REFERENCES "user".story(id) ON DELETE CASCADE,
    user_id   UUID NOT NULL,
    viewed_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    UNIQUE(story_id, user_id)
);
CREATE INDEX IF NOT EXISTS user_idx_story_view_user ON "user".story_view (user_id);

CREATE TABLE IF NOT EXISTS "user".faq (
    id                 UUID PRIMARY KEY DEFAULT uuid_generate_v4() NOT NULL,
    title_uz           TEXT, title_ru TEXT, title_en TEXT,
    answer_uz          TEXT, answer_ru TEXT, answer_en TEXT,
    is_deleted         BOOLEAN DEFAULT FALSE,
    created_date       TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    last_modified_date TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE IF NOT EXISTS "user".legal_document (
    id                 UUID PRIMARY KEY DEFAULT uuid_generate_v4() NOT NULL,
    type               TEXT NOT NULL,
    text_uz            TEXT, text_ru TEXT, text_en TEXT,
    created_date       TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    last_modified_date TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
);

INSERT INTO "user".blog (id, title_uz, title_ru, title_en, body_uz, body_ru, body_en, image, date, is_home, is_send, is_deleted, created_date, last_modified_date) SELECT id, title_uz, title_ru, title_en, body_uz, body_ru, body_en, image, date, is_home, is_send, is_deleted, created_date, last_modified_date FROM notification.blog ON CONFLICT (id) DO NOTHING;
INSERT INTO "user".banner (id, title_uz, title_ru, title_en, image, link, sort_order, is_active, is_deleted, created_date, last_modified_date) SELECT id, title_uz, title_ru, title_en, image, link, sort_order, is_active, is_deleted, created_date, last_modified_date FROM notification.banner ON CONFLICT (id) DO NOTHING;
INSERT INTO "user".story (id, title_uz, title_ru, title_en, avatar, items, is_deleted, created_date, last_modified_date) SELECT id, title_uz, title_ru, title_en, avatar, items, is_deleted, created_date, last_modified_date FROM notification.story ON CONFLICT (id) DO NOTHING;
INSERT INTO "user".story_view (id, story_id, user_id, viewed_at) SELECT id, story_id, user_id, viewed_at FROM notification.story_view ON CONFLICT (id) DO NOTHING;
INSERT INTO "user".faq (id, title_uz, title_ru, title_en, answer_uz, answer_ru, answer_en, is_deleted, created_date, last_modified_date) SELECT id, title_uz, title_ru, title_en, answer_uz, answer_ru, answer_en, is_deleted, created_date, last_modified_date FROM notification.faq ON CONFLICT (id) DO NOTHING;
INSERT INTO "user".legal_document (id, type, text_uz, text_ru, text_en, created_date, last_modified_date) SELECT id, type, text_uz, text_ru, text_en, created_date, last_modified_date FROM notification.legal_document ON CONFLICT (id) DO NOTHING;

DROP TABLE IF EXISTS notification.story_view;
DROP TABLE IF EXISTS notification.story;
DROP TABLE IF EXISTS notification.blog;
DROP TABLE IF EXISTS notification.banner;
DROP TABLE IF EXISTS notification.faq;
DROP TABLE IF EXISTS notification.legal_document;
